examples.code:
HStack(spacing: 0) {
    MonarchTabs("Project sections", selection: $section, items: Array(sections.prefix(3)))
    Menu {
        Picker("More sections", selection: $section) {
            ForEach(sections.dropFirst(3)) { item in
                Text(item.title).tag(item.value)
            }
        }
        .pickerStyle(.inline)
    } label: {
        Label(
            sections.dropFirst(3).first { $0.value == section }?.title ?? "More",
            systemImage: "chevron.down"
        )
    }
    .buttonStyle(.monarch(.ghost, size: .sm))
}
